int main(void){static uint8_t data[0x400000];Dk1RomImage rom;Dk1LevelTerrainConfig c={0};Dk1PpuBgLayout l={0};Dk1DynamicStreamUpdate u={0};Dk1VramImage v;Dk1DynamicTileStreamStats s;size_t off=((0xC0u&0x3Fu)<<16);assert(dk1_rom_image_init(&rom,data,sizeof(data)));c.map_snes=0xC00000u;c.visual_bank=0xC0u;c.visual_block_base=0x0100u;data[off]=1u;for(size_t i=0;i<16;i++){uint16_t w=(uint16_t)(0x200u+i);size_t p=off+0x120u+i*2u;data[p]=(uint8_t)w;data[p+1]=(uint8_t)(w>>8u);}l.screen_base_word=0x1000u;l.tilemap_width=64u;l.tilemap_height=64u;dk1_vram_image_init(&v);u.changed=true;u.old_first=0;u.new_first=0;u.new_last=0;u.columns_entered=1;assert(dk1_dynamic_tile_stream_apply(&rom,&c,&l,&u,&v,&s));assert(s.map_columns==1u&&s.tile_words==256u);assert(v.bytes[0x2000]==0x00u&&v.bytes[0x2001]==0x02u);u.changed=false;assert(dk1_dynamic_tile_stream_apply(&rom,&c,&l,&u,&v,&s)&&s.tile_words==0u);return 0;}
